#!/usr/bin/env node
/**
 * Writes `styles/pattern/tokens.css`: the VALUES of the generated token stylesheet, and nothing else.
 *
 * Source: `components/registry/n1-tokens/mzizi-tokens-globals.css` (GENERATED by `pnpm tokens:sync`).
 * This keeps the custom-property declarations of its `:root`, `[data-theme="dark"]` and
 * `@media … { :root }` blocks, and the `prefers-color-scheme` dark mirror of the dark block.
 * It drops Tailwind (`@import`, `@theme`, `@utility`, `@layer`), the `[data-brand]` blocks and
 * every rule that is not a custom property, so the output has no selector except `:root`,
 * `[data-theme]` and the colour-scheme media query. (Issue #708, pattern PR.)
 *
 * `--check` fails when the committed file has drifted from its source.
 */
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const SOURCE = path.join(root, "components/registry/n1-tokens/mzizi-tokens-globals.css");
const OUT = path.join(root, "styles/pattern/tokens.css");
const check = process.argv.includes("--check");

/** Strip /* … *\/ comments, keeping strings intact. */
function stripComments(css) {
  let out = "";
  let i = 0;
  while (i < css.length) {
    if (css.startsWith("/*", i)) {
      const end = css.indexOf("*/", i + 2);
      if (end < 0) throw new Error("unterminated comment");
      i = end + 2;
    } else if (css[i] === '"' || css[i] === "'") {
      const q = css[i];
      let j = i + 1;
      while (j < css.length && css[j] !== q) j += css[j] === "\\" ? 2 : 1;
      out += css.slice(i, j + 1);
      i = j + 1;
    } else {
      out += css[i];
      i += 1;
    }
  }
  return out;
}

/** Top-level rules of a stylesheet or block body: { prelude, body } for each `prelude { body }`. */
function parseBlocks(css) {
  const items = [];
  let depth = 0;
  let boundary = 0;
  let open = -1;
  let inStr = null;
  for (let i = 0; i < css.length; i += 1) {
    const c = css[i];
    if (inStr) {
      if (c === "\\") i += 1;
      else if (c === inStr) inStr = null;
      continue;
    }
    if (c === '"' || c === "'") inStr = c;
    else if (c === "{") {
      if (depth === 0) open = i;
      depth += 1;
    } else if (c === "}") {
      depth -= 1;
      if (depth === 0) {
        items.push({ prelude: css.slice(boundary, open).trim(), body: css.slice(open + 1, i) });
        boundary = i + 1;
      }
    } else if (c === ";" && depth === 0) boundary = i + 1;
  }
  return items;
}

/** Custom-property declarations of a block body, one per line, comments removed. */
function customProps(body) {
  const decls = [];
  let depth = 0;
  let cur = "";
  for (const ch of body) {
    if (ch === "{") depth += 1;
    if (ch === "}") depth -= 1;
    if (depth === 0 && ch === ";") {
      decls.push(cur.trim());
      cur = "";
    } else if (depth === 0) cur += ch;
  }
  return decls.filter((d) => d.startsWith("--")).map((d) => `  ${d};`);
}

const src = stripComments(readFileSync(SOURCE, "utf8"));
const top = parseBlocks(src);

const rootDecls = [];
const darkDecls = [];
const mediaOut = [];

for (const block of top) {
  const selectors = block.prelude.split(",").map((x) => x.trim());
  if (selectors.includes(":root")) rootDecls.push(...customProps(block.body));
  else if (selectors.includes('[data-theme="dark"]')) darkDecls.push(...customProps(block.body));
  else if (block.prelude.startsWith("@media")) {
    // only `@media … { :root { … } }` blocks: the density and size tiers
    const inner = parseBlocks(block.body).filter((b) => b.prelude === ":root");
    if (inner.length === 0) continue;
    const decls = inner.flatMap((b) => customProps(b.body));
    if (decls.length) mediaOut.push(`${block.prelude} {\n  :root {\n${decls.map((d) => `  ${d}`).join("\n")}\n  }\n}`);
  }
}

if (rootDecls.length === 0 || darkDecls.length === 0) {
  throw new Error("token source has no :root or [data-theme=\"dark\"] custom properties");
}

const header = `/* GENERATED by scripts/generate-pattern-tokens.mjs from components/registry/n1-tokens/mzizi-tokens-globals.css.
 * Do not edit: change the source with \`pnpm tokens:sync\`, then \`pnpm pattern:generate\`.
 * Values only: custom properties under :root, [data-theme="dark"] and the colour-scheme query. */`;

const out = [
  header,
  ":root {",
  ...rootDecls,
  "}",
  '[data-theme="dark"] {',
  ...darkDecls,
  "}",
  "@media (prefers-color-scheme: dark) {",
  '  :root:not([data-theme]) {',
  ...darkDecls.map((d) => `  ${d}`),
  "  }",
  "}",
  ...mediaOut,
  "",
].join("\n");

if (check) {
  let committed = "";
  try {
    committed = readFileSync(OUT, "utf8");
  } catch {
    // missing file counts as drift
  }
  if (committed !== out) {
    console.error(`styles/pattern/tokens.css has drifted from its source; run pnpm pattern:generate`);
    process.exit(1);
  }
  console.log("styles/pattern/tokens.css is up to date");
} else {
  writeFileSync(OUT, out);
  console.log(`wrote ${path.relative(root, OUT)} (${rootDecls.length} light, ${darkDecls.length} dark declarations, ${mediaOut.length} media tiers)`);
}
